#else
#define debug(...)
#define debugArr(...)
#endif
int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    vector<long long> sums;
    for (int x = 0; x <= 30; ++x) {
        long long px = 1LL << x;
        for (int y = x + 1; y <= 30; ++y) {
            long long py = 1LL << y;
            sums.push_back(px + py);
        }
    }
    sort(sums.begin(), sums.end());

    sums.erase(unique(sums.begin(), sums.end()), sums.end());
    int q;
    cin >> q;
    while (q--) {
        long long n;
        cin >> n;

        auto it = lower_bound(sums.begin(), sums.end(), n);
        long long ans = LLONG_MAX;
        if (it != sums.end()) ans = min(ans, llabs(*it - n));
        if (it != sums.begin()) {
            --it;
            ans = min(ans, llabs(*it - n));
        }
        cout << ans << '\n';
    }
}